/**
 * Tests for MIDI export timing, transposition, value clamping and multi-track output
 * (decodes the generated bytes rather than only checking the header)
 */

import { describe, it, expect } from 'vitest';
import { buildMidiFromProgression, buildMidiFromTracks } from '../../utils/midiExport.js';

const TPQ = 480;

/** Decode a MIDI file into { format, tracks: [{ name, tempo, notes: [{ beat, on, note, velocity }] }] } */
function decodeMidi(bytes) {
    const format = bytes[9];
    const trackCount = (bytes[10] << 8) | bytes[11];
    const tracks = [];
    let pos = 14;
    for (let t = 0; t < trackCount; t++) {
        const len = (bytes[pos + 4] << 24) | (bytes[pos + 5] << 16) | (bytes[pos + 6] << 8) | bytes[pos + 7];
        let i = pos + 8;
        const end = i + len;
        let tick = 0;
        const track = { name: null, tempo: null, notes: [] };
        while (i < end) {
            let delta = 0, b;
            do { b = bytes[i++]; delta = (delta << 7) | (b & 0x7f); } while (b & 0x80);
            tick += delta;
            const status = bytes[i];
            if (status === 0xff) {
                const type = bytes[i + 1], size = bytes[i + 2];
                const data = bytes.slice(i + 3, i + 3 + size);
                if (type === 0x51) track.tempo = Math.round(60000000 / ((data[0] << 16) | (data[1] << 8) | data[2]));
                if (type === 0x03) track.name = new TextDecoder().decode(data);
                i += 3 + size;
            } else if ((status & 0xf0) === 0xc0) {
                i += 2;
            } else {
                track.notes.push({ beat: tick / TPQ, on: (status & 0xf0) === 0x90, note: bytes[i + 1], velocity: bytes[i + 2] });
                i += 3;
            }
        }
        tracks.push(track);
        pos = end;
    }
    return { format, tracks };
}

const major = { notes: [0, 4, 7] };
const onsets = (track) => [...new Set(track.notes.filter(n => n.on).map(n => n.beat))];

describe('buildMidiFromProgression timing', () => {
    it('places chords at their beat positions', () => {
        const midi = decodeMidi(buildMidiFromProgression({
            progression: [{ beat: 0, chord: major }, { beat: 4, chord: major }]
        }));
        expect(onsets(midi.tracks[0])).toEqual([0, 4]);
    });

    it('ends a chord gapBeats before the next one', () => {
        const midi = decodeMidi(buildMidiFromProgression({
            progression: [{ beat: 0, chord: major }, { beat: 1, chord: major }],
            noteLengthBeats: 3.2,
            gapBeats: 0.4
        }));
        const firstOff = midi.tracks[0].notes.find(n => !n.on);
        expect(firstOff.beat).toBeCloseTo(0.6);
    });

    it('caps the gap so a chord never shrinks to nothing', () => {
        const midi = decodeMidi(buildMidiFromProgression({
            progression: [{ beat: 0, chord: major }, { beat: 1, chord: major }],
            gapBeats: 1.5
        }));
        const firstOff = midi.tracks[0].notes.find(n => !n.on);
        expect(firstOff.beat).toBeCloseTo(0.5);
    });

    it('spaces items without a beat sequentially', () => {
        const midi = decodeMidi(buildMidiFromProgression({
            progression: [major, major],
            noteLengthBeats: 2,
            gapBeats: 1
        }));
        expect(onsets(midi.tracks[0])).toEqual([0, 3]);
    });

    it('ignores negative beats instead of writing a corrupt delta', () => {
        const midi = decodeMidi(buildMidiFromProgression({
            progression: [{ beat: -1, chord: major }, { beat: 4, chord: major }]
        }));
        expect(onsets(midi.tracks[0])).toEqual([0, 4]);
    });
});

describe('buildMidiFromProgression pitch and values', () => {
    it('transposes by the tonic', () => {
        const midi = decodeMidi(buildMidiFromProgression({ progression: [{ beat: 0, chord: major }], tonic: 2 }));
        expect(midi.tracks[0].notes.filter(n => n.on).map(n => n.note)).toEqual([62, 66, 69]);
    });

    it('clamps velocity instead of wrapping (128 used to become 0 = note-off)', () => {
        const loud = decodeMidi(buildMidiFromProgression({ progression: [{ beat: 0, chord: major }], velocity: 128 }));
        const silent = decodeMidi(buildMidiFromProgression({ progression: [{ beat: 0, chord: major }], velocity: 0 }));
        expect(loud.tracks[0].notes[0].velocity).toBe(127);
        expect(silent.tracks[0].notes[0].velocity).toBe(1);
    });

    it('clamps tempo to a valid range', () => {
        const midi = decodeMidi(buildMidiFromProgression({ progression: [{ beat: 0, chord: major }], tempo: -60 }));
        expect(midi.tracks[0].tempo).toBe(20);
    });
});

describe('buildMidiFromTracks', () => {
    it('writes a format 1 file with a tempo track and one named track per non-empty progression', () => {
        const midi = decodeMidi(buildMidiFromTracks({
            tempo: 90,
            tracks: [
                { name: 'Track 1', progression: [{ beat: 0, chord: major }] },
                { name: 'Track 2', progression: [] },
                { name: 'Track 3', progression: [{ beat: 2, chord: major }] }
            ]
        }));
        expect(midi.format).toBe(1);
        expect(midi.tracks).toHaveLength(3);
        expect(midi.tracks[0].tempo).toBe(90);
        expect(midi.tracks[1].name).toBe('Track 1');
        expect(midi.tracks[2].name).toBe('Track 3');
        expect(onsets(midi.tracks[2])).toEqual([2]);
    });

    it('returns null when no track has chords', () => {
        expect(buildMidiFromTracks({ tracks: [{ name: 'Track 1', progression: [] }] })).toBeNull();
    });
});
